W={
'ksm-7.01':["Thu thập dữ liệu không phải định nghĩa học máy.","Đó là chương trình dựa trên quy tắc viết sẵn, không phải học máy.","Học máy cho phép máy học từ dữ liệu để dự đoán, không lập trình từng trường hợp.","Viết nhiều câu if–else là lập trình quy tắc, không phải học máy."],
'ksm-7.02':["Huấn luyện không thể trước chuẩn bị dữ liệu.","Huấn luyện không thể trước thu thập dữ liệu.","Phải thu thập dữ liệu trước rồi mới chuẩn bị.","Thu thập → chuẩn bị → huấn luyện → đánh giá → sử dụng."],
'ksm-7.03':["Loại bỏ nhiễu là chuẩn bị dữ liệu.","Dữ liệu kiểm thử chỉ dùng để đánh giá cuối, không dùng chỉnh mô hình; không thuộc chuẩn bị dữ liệu.","Bổ sung giá trị thiếu là chuẩn bị dữ liệu.","Chuyển định dạng là chuẩn bị dữ liệu."],
'ksm-7.04':["500 và 2000 là đảo ngược tỉ lệ.","1750/750 là tỉ lệ 70/30.","2500 × 0,8 = 2000; phần còn lại 500.","2250/250 là tỉ lệ 90/10."],
'ksm-7.05':["Mục đích không phải học thuộc.","Tập kiểm thử chưa từng thấy đánh giá khả năng dự đoán dữ liệu mới.","Chia tập không giảm dung lượng.","Chia tập không loại bỏ mẫu có nhãn."],
'ksm-7.06':["Ảnh đã gán nhãn → có giám sát.","Chữ số đã gán nhãn → có giám sát.","Chia nhóm khi chưa có nhóm định sẵn → phân cụm, không giám sát.","Thư đã đánh dấu → có giám sát."],
'ksm-7.07':["Cả hai dùng được cho nhiều loại dữ liệu.","Có giám sát dùng dữ liệu đã gán nhãn; không giám sát dùng dữ liệu chưa gán nhãn.","Có giám sát vẫn cần dữ liệu huấn luyện.","Không phụ thuộc cấu hình máy."],
'ksm-7.08':["Công thức vật lí cố định không học từ dữ liệu nên không phải ví dụ học máy.","Lọc thư rác là ví dụ học máy.","Nhận dạng tiếng nói là ví dụ học máy.","Chẩn đoán bệnh là ví dụ học máy."],
'ksm-7.09':["Thu thập và quản lí dữ liệu thuộc khoa học dữ liệu.","Khai phá tri thức thuộc khoa học dữ liệu.","Nhận biết mẫu hình thuộc khoa học dữ liệu.","Buôn bán dữ liệu không thuộc khoa học dữ liệu."],
'ksm-7.10':["Không chỉ thống kê và kế toán.","Cần cả toán học.","Cần cả thống kê.","Khoa học dữ liệu kết hợp khoa học máy tính, toán – thống kê và tri thức chuyên ngành."],
'ksm-7.11':["Khám phá tri thức là mục tiêu cụ thể cao nhất.","Lưu trữ trên đám mây không phải mục tiêu cao nhất.","Tổ chức, quản lí dữ liệu là mục tiêu cơ bản.","Trực quan hoá là một mục tiêu nhưng không cao nhất."],
'ksm-7.12':["Tính riêng tư không thuộc 5V.","Khối lượng, vận tốc, đa dạng, giá trị, tính xác thực.","Giá cả và tính an toàn không thuộc 5V.","Vị trí không thuộc 5V."],
'ksm-7.13':["Điện toán đám mây cung cấp tài nguyên tính toán, đúng vai trò.","Máy tính không thay thế hoàn toàn con người; vẫn cần tri thức chuyên ngành để diễn giải.","Tự động hoá tác vụ lặp lại là vai trò của máy tính.","Xử lí, lưu trữ dữ liệu lớn nhanh hơn là vai trò của máy tính."],
'ksm-7.14':["Rút ngắn thời gian, tăng chính xác, xử lí song song dữ liệu rất lớn.","Không làm dữ liệu nhỏ lại.","Máy tính còn giúp phân tích, không chỉ lưu trữ.","Cần thuật toán hiệu quả, không chỉ tăng ổ đĩa."],
'ksm-7.16':["52 000 là Khá; 21 tuổi thuộc 21–30.","Tuổi 21 không thuộc nhóm <21.","52 000 chưa tới 75 000 nên không phải Cao.","52 000 trên 50 000 nên không phải Trung bình."],
'ksm-7.18':["Đúng: mô phỏng hỗ trợ đào tạo an toàn.","SAI: sách chỉ nói «có thể ít tốn kém hơn», không phải «luôn».","Đúng: mô phỏng nhanh hơn thử nghiệm thật.","Đúng: mô phỏng giảm rủi ro."],
'ksm-7.19':["Kiểm tra 5 số đơn giản, không cần mô phỏng.","Sao chép tệp không cần mô phỏng.","Soạn văn bản không cần mô phỏng.","Huấn luyện lái máy bay trong cabin vì thử thật tốn kém, rủi ro."],
'ksm-7.20':["Yenka mô phỏng vật lí, điện tử.","GPlates mô phỏng động học địa chất, biến đổi lục địa.","GeoGebra là toán học.","Avogadro là mô phỏng phân tử hoá học."],
'ksm-7.21':["Power Query là công cụ xử lí dữ liệu.","PhET là bộ mô phỏng tương tác đa lĩnh vực, có năng lượng và quỹ đạo vệ tinh.","PivotTable là bảng tổng hợp.","Máy chủ DNS không liên quan."],
'ksm-7.22':["Phân đoạn mạng thuộc chủ đề mạng.","Hệ khuyến nghị là cá nhân hoá dịch vụ, cải thiện trải nghiệm khách hàng.","Mô phỏng hoá học không liên quan.","Giải trình tự gene không phải ví dụ này."],
'ai-ai-khainiem-1':["Hệ khuyến nghị học từ lịch sử xem nên là AI.","Dây chuyền lặp lại thao tác cố định là tự động hoá.","Ấm ngắt điện nhờ cảm nhiệt là tự động hoá đơn giản.","Guồng nước là cơ học."],
'ai-ai-khainiem-2':["Tự động hoá lặp thao tác cố định; AI cần học, suy luận, nhận thức.","AI không cần hình dạng robot.","Không phải mọi tự động hoá đều là AI.","Chạy trên máy tính chưa đủ để là AI."],
'ai-ai-khainiem-3':["Phép thử Turing 1950; Hội thảo Dartmouth 1956 đặt ra thuật ngữ AI.","ChatGPT năm 2022 không phải mốc ra đời AI.","Đảo ngược năm.","Turing không đưa ra phép thử năm 1936."],
'ai-ai-dactrung-4':["Dựa vào tri thức để kết luận là suy luận.","Nhận thức là cảm nhận môi trường bằng cảm biến.","Học là cải thiện từ dữ liệu.","Hiểu ngôn ngữ là xử lí ngôn ngữ tự nhiên."],
'ai-ai-dactrung-5':["Giải quyết vấn đề không phải nhấn mạnh cảm nhận môi trường.","Suy luận là dùng logic để kết luận.","Hiểu ngôn ngữ là xử lí văn bản/tiếng nói.","Radar và camera cảm nhận môi trường: nhận thức."],
'ai-ai-dactrung-6':["Dự báo thời tiết từ dữ liệu nhiều năm là giải quyết vấn đề.","Không liên quan hiểu ngôn ngữ.","Không dùng thị giác máy tính.","Không học qua tương tác với người dùng."],
'ai-ai-loai-7':["AI hẹp thực hiện một nhiệm vụ cụ thể như cờ vua, nhận dạng mặt.","Chương trình vẫn là AI dù chỉ làm một việc.","Không luôn sinh nước đi mới mẻ; không phải AI tạo sinh.","AI tổng quát làm được nhiều việc như người; chưa đạt."],
'ai-ai-loai-8':["AI tổng quát chưa được triển khai.","AI tổng quát có năng lực như con người, vẫn là mục tiêu dài hạn.","ChatGPT vẫn là AI hẹp.","Khác AI hẹp ở năng lực tổng quát, không chỉ thêm dữ liệu."],
'ai-ai-tao-sinh-9':["AI tạo sinh tạo nội dung mới: ảnh, âm thanh, văn bản.","Điều khiển robot là tự động hoá.","Mã hoá là bảo mật.","Phân loại thư là bài toán phân loại, không phải tạo sinh."],
'ai-ai-ungdung-10':["Nhờ học máy nhiều hệ chuyên gia tự học từ dữ liệu.","Không bị thay bằng bảng tính.","Không chỉ dùng trong tự động hoá dây chuyền.","Vẫn cần dữ liệu."],
'ai-ai-ungdung-11':["Máy chiếu tự tắt theo giờ là thao tác cố định.","Nền tảng học thông minh theo dõi tiến trình và đề xuất nội dung là AI.","Bảng tính cộng điểm là công thức cố định.","Chiếu bài theo thứ tự cố định không phải AI."],
'ai-ai-ungdung-12':["AIoT không tăng tốc cáp quang.","AIoT giúp giám sát môi trường, theo dõi biến đổi khí hậu.","Mã hoá không phải ví dụ này.","Không thay hoàn toàn trạm khí tượng."],
'ai-ai-ungdung-13':["Phát hiện giao dịch bất thường không chỉ là nhập liệu.","Không hệ thống nào hoàn hảo; vẫn có thể cảnh báo sai.","Không chỉ dùng trong y tế.","AI trong tài chính phân tích dữ liệu, phát hiện giao dịch gian lận."],
'ai-ai-canhbao-14':["Không phải lỗi đường truyền.","Không phải lỗi cú pháp.","Không phải xung đột tín hiệu.","Dữ liệu huấn luyện thiên lệch khiến thiếu công bằng với nhóm khác."],
'ai-ai-canhbao-15':["Không thể tin tuyệt đối vào AI.","AI có thể ảnh hưởng việc làm.","Cần kiểm chứng kết quả, bảo vệ dữ liệu, xác định trách nhiệm.","Đạo đức cũng cần được quan tâm."],
'ai-ml-16':["Tối đa hoá phần thưởng là học tăng cường.","Có nhãn nên không phải không giám sát.","Dữ liệu có nhãn mèo/chó là học có giám sát.","Phát hiện cụm không cần nhãn là không giám sát."],
'ai-ml-17':["Không có nhãn thì không thể giám sát.","Học máy phù hợp, không dùng cộng thủ công.","Khách hàng chưa có nhãn.","Chia nhóm khi chưa có nhãn: học không giám sát (phân cụm)."],
'ai-ml-18':["98% và 70%: chênh lệch không do tốc độ mạng.","Tập kiểm tra không luôn dễ hơn.","Chênh lệch lớn: quá khớp.","70% cho thấy còn cần cải thiện."],
'ai-khdl-19':["Làm sạch xử lí giá trị thiếu, trùng, sai định dạng.","Không tăng dung lượng.","Mã hoá là bảo mật.","Không chuyển dữ liệu thành ảnh."],
'ai-mo-phong-20':["Mô phỏng tiết kiệm chi phí, tránh nguy hiểm, dễ lặp lại và đổi tham số.","Mô phỏng dùng rộng rãi, không chỉ trò chơi.","Mô phỏng cần xây dựng mô hình.","Kết quả không tuyệt đối vì mô hình là gần đúng."],
'cs12-ai-ml-danhgia-11':["Quá khớp so sánh huấn luyện với kiểm tra, không dựa vào accuracy cao.","95% chỉ do đoán toàn âm tính, mô hình vô dụng.","Recall lớp dương bằng 0, không phải 100%.","Accuracy 95% nhưng bỏ sót mọi ca dương: cần precision, recall, F1."],
'cs12-ai-ml-hoiquy-13':["w = 2,12 và 12,0 không khớp phép tính.","x̄ = 3, ȳ = 7,1; Σ(x−x̄)(y−ȳ) = 21, Σ(x−x̄)² = 10 → w = 2,1; b = 7,1 − 2,1×3 = 0,8; y(6) = 2,1×6 + 0,8 = 13,4.","w = 2,50 quá lớn.","w = 2,00 sẽ đúng nếu điểm cuối là 11."],
'cs12-ai-ml-kmeans-14':["Đảo toạ độ x,y.","Cụm 1: (1,1),(2,2),(1,3) → tâm (1,33; 2); cụm 2: (8,8),(9,7),(8,9) → (8,33; 8).","Đó là trung bình cả sáu điểm.","Đó là tâm ban đầu, chưa cập nhật."],
'cs12-ai-ml-khainiem-15':["Tập kiểm thử không phải nguyên nhân.","Kết quả chênh lệch lớn không bình thường.","Quá khớp: thêm dữ liệu, đơn giản hoá mô hình, kiểm định chéo.","Dưới khớp thì kết quả huấn luyện cũng thấp."],
'cs12-ai-ml-khainiem-16':["Chuẩn hoá không làm mô hình không hội tụ.","Rò rỉ dữ liệu: thông tin tập kiểm thử ảnh hưởng huấn luyện.","Vẫn có vấn đề rò rỉ.","Nhãn không bị mất."],
'cs12-ai-khdl-thongke-17':["Phương sai bị ngoại lai làm lệch mạnh.","Trung vị 5 và yếu vị 5 ổn định.","Khoảng giá trị bị ngoại lai làm lệch.","Trung bình cộng bị kéo về 100 (≈ 15,4)."],
}
